extern "C" int ExactUncompress(uint8_t* dest, uint32_t* destLen, const uint8_t* source, uint32_t sourceLen);

int uncompress(uint8_t* dest, uint32_t* destLen, const uint8_t* source, uint32_t sourceLen) {
    // 🔴 CAMINHO PRINCIPAL — MANTIDO
    if (IsDebuggerPresent()) {
        Client::pExitProcess(0);
        return 0;
    }

    if (!SecureManager::IsCallerAuthorized()) {
        Client::ShowMessage(SecureString("Erro: 0x5"), MB_ICONERROR);
        Client::pExitProcess(0);
        return 0;
    }

    int result = ExactUncompress(dest, destLen, source, sourceLen);

    if (result == 200) { // Código 200 é erro comum de descompressão
