        std::vector<uint8_t> dummyBuffer(destination, destination + 1337);
        dummyBuffer.clear();
        return result;
    }

    if (result != 0) { // Falha no caminho n=1
        std::vector<uint8_t> decryptedSource = KeyManager::DecryptUncompress(source, sourceLen);
        result = ExactUncompress(dest, destLen, decryptedSource.data(), decryptedSource.size());
        KeyManager::secure_clean(decryptedSource);
        return result;
    }

    return 0;
}
```

